custom_coloring.source:
// The Frothy Basin colouring: which attractor a pixel's orbit landed on,
// a band of the palette each, and how soon, a shade within the band --
// Fractint's colouring of its frothybasin type (Xfractint 20.04p16,
// common/miscfrac.c, calcfroth's 256-colour branch). Fractint drew it
// with its froth3 and froth6 maps, a hue to a band; any palette of three
// (or six) parts reads as they did.
//
// The formula's `a` and Mapping decide the lines the orbits land on; a
// colouring reads only the orbit, so it takes them again: set them as
// the formula's. A pixel that left, or never landed, takes the solid
// colour (Fractint's colour 0).

const PARAMS = #{
    a: #{ value: 1.028713768218725, caption: "a", hint: "The formula's a" },
    mapping: #{ value: 0, caption: "Mapping", choices: ["Once (3 basins)", "Twice (6 basins)"], hint: "The formula's Mapping" },
    shade: #{ value: 0, caption: "Shade", choices: ["By count, to the band's length", "By count over the iteration limit"], hint: "Fractint's two schemes: the count up to the band's length (85 colours of 256 for three basins), or the count over the whole iteration limit (its alternate colouring)" },
};

const INFO = #{ title: "Frothy Basin", region: "outside" };

// Which attractor's line `z` has landed on, 1 to 6, or 0 for none:
// Fractint's test and its numbering, on the formula's lines and marks
// (frothy-basin.rhai, `froth_landed`).
fn froth_attractor(z, a, twice) {
    let close = 1.0e-6;
    let slope = sqrt(3.0);
    // Fractint's critical a, 1.0287137682187249: a parameter is kept in
    // f32, which rounds that value itself just past it, so the test
    // allows the rounding -- at the default there are three basins.
    let three = a.abs() <= 1.02871388;
    let n = if three { if twice { 6 } else { 3 } } else { if twice { 3 } else { 2 } };
    let k = 0.75 * a * a;
    let t1 = 0.25 - 0.5 - k;
    let t2 = t1 * t1 - t1 - k;
    let t3 = t2 * t2 - t2 - k;
    let t4 = t3 * t3 - t3 - k;
    let y0 = a / 2.0;
    let s = slope / 2.0;
    let x = z.re;
    let y = z.im;
    if (y0 - y).abs() < close && x >= t1 && x <= t2 {
        if (!twice && n == 2) || (twice && n == 3) {
            1
        } else if x <= t3 {
            1
        } else if x >= t4 {
            if twice { 2 } else { 1 }
        } else {
            0
        }
    } else if (slope * x - a - y).abs() < close && x <= -0.5 * t1 + y0 * s && x >= -0.5 * t2 + y0 * s {
        if !twice && n == 2 {
            2
        } else if twice && n == 3 {
            3
        } else if x >= -0.5 * t3 + y0 * s {
            if twice { 4 } else { 2 }
        } else if x <= -0.5 * t4 + y0 * s {
            if twice { 6 } else { 3 }
        } else {
            0
        }
    } else if (-slope * x - a - y).abs() < close && x <= -0.5 * t1 - y0 * s && x >= -0.5 * t2 - y0 * s {
        if !twice && n == 2 {
            2
        } else if twice && n == 3 {
            2
        } else if x >= -0.5 * t3 - y0 * s {
            if twice { 5 } else { 3 }
        } else if x <= -0.5 * t4 - y0 * s {
            if twice { 3 } else { 2 }
        } else {
            0
        }
    } else {
        0
    }
}

fn finish(s, z, p, ctx) {
    let twice = p.mapping == 1;
    let basin = froth_attractor(z, p.a, twice);
    // Fractint's bands: 255 colours over at least three, its two- and
    // three-basin pictures alike; a pixel's shade the count, at least 1.
    let three = p.a.abs() <= 1.02871388;
    let bands = if three && twice { 6.0 } else { 3.0 };
    let shades = if bands == 6.0 { 42.0 } else { 85.0 };
    let n = to_float(ctx.numiter);
    let count = if p.shade == 0 {
        if n > shades { shades } else { n }
    } else {
        (shades * n / to_float(ctx.maxiter)).floor()
    };
    let shade = if count < 1.0 { 1.0 } else { count };
    if basin == 0 {
        #{ index: 0.0, solid: true }
    } else {
        #{ index: (shade + shades * to_float(basin - 1)) / 256.0, solid: false }
    }
}

custom_formula.source:
// Frothy Basin, Fractint's type (Wesley Loewer's, after the riddled
// basins James Alexander drew): z^2 + conj((-1 + a i) z), a map with
// three attractors -- each settling on one of three lines, y = a/2 and
// its turns by 120 degrees -- whose basins froth into one another.
// Ported from Xfractint 20.04p16 (common/miscfrac.c: froth_setup and
// calcfroth, the floating-point path; the defaults, the view and the
// bailout from common/fractalp.c).
//
// A pixel stops when its orbit lands within 1e-6 of an attractor's line
// (`froth_landed`, Fractint's test), or leaves the bailout's circle.
// The test reads the iterate alone -- nothing carried but z -- so deep
// zoom derives its equations. The Frothy Basin colouring
// (`frothy-basin-coloring.rhai`) colours the basins as Fractint does;
// its `a` and Mapping are this formula's, to set alike.

const PARAMS = #{
    a: #{ value: 1.028713768218725, caption: "a", hint: "The map's parameter. Up to 1.0287137682 (Fractint's critical value) there are three basins; past it, two" },
    mapping: #{ value: 0, caption: "Mapping", choices: ["Once (3 basins)", "Twice (6 basins)"], hint: "Map once a pass, or twice: twice splits each basin in two (Fractint's first parameter, 1 or 2)" },
    bailout: #{ value: 7.0, min: 7.0, caption: "Bailout", hint: "The squared radius past which a pixel has left (at least 7, as Fractint keeps it)" },
};

const INFO = #{ title: "Frothy Basin", center: complex(0.0, -0.255), magn: 0.9523809523809523, maxiter: 150 };

fn start(pixel, p, ctx) {
    #{ z: pixel }
}

// Whether `z` has landed on an attractor: Fractint's test, which sets
// marks along the top line by the line's own map -- x^2 - x - 3a^2/4,
// from its minimum at x = 0.5 -- and turns them 120 degrees either way
// for the other two lines. Written as one comparison, for `escaped`: a
// point on a line counts unless it lies between the third and fourth
// marks, which only a three-basin picture (a at most the critical value)
// keeps waiting. Which attractor it is, the colouring tells.
fn froth_landed(z, a) {
    let close = 1.0e-6;
    let slope = sqrt(3.0);
    // Fractint's critical a, 1.0287137682187249: a parameter is kept in
    // f32, which rounds that value itself just past it, so the test
    // allows the rounding -- at the default there are three basins.
    let three = a.abs() <= 1.02871388;
    let k = 0.75 * a * a;
    let t1 = 0.25 - 0.5 - k;
    let t2 = t1 * t1 - t1 - k;
    let t3 = t2 * t2 - t2 - k;
    let t4 = t3 * t3 - t3 - k;
    let y0 = a / 2.0;
    let s = slope / 2.0;
    let x = z.re;
    let y = z.im;
    let top = (y0 - y).abs() < close && x >= t1 && x <= t2;
    let right = (slope * x - a - y).abs() < close && x <= -0.5 * t1 + y0 * s && x >= -0.5 * t2 + y0 * s;
    let left = (-slope * x - a - y).abs() < close && x <= -0.5 * t1 - y0 * s && x >= -0.5 * t2 - y0 * s;
    (top && (!three || x <= t3 || x >= t4))
        || (!top && right && (!three || x >= -0.5 * t3 + y0 * s || x <= -0.5 * t4 + y0 * s))
        || (!top && !right && left && (!three || x >= -0.5 * t3 - y0 * s || x <= -0.5 * t4 - y0 * s))
}

// One map, z^2 + conj((-1 + a i) z), in Fractint's arithmetic and its
// order: the orbits are chaotic, and the order of a rounding moves a
// count.
fn froth_map(z, a) {
    let x = z.re;
    let y = z.im;
    complex(x * x - y * y - x - a * y, y + ((x + x) * y - a * x))
}

fn step(s, p) {
    s.z = froth_map(s.z, p.a);
    if p.mapping == 1 {
        s.z = froth_map(s.z, p.a);
    }
    s
}

fn escaped(s, p) {
    froth_landed(s.z, p.a) || s.z.norm_sqr() > p.bailout
}

// Volterra-Lotka, Fractint's type after The Beauty of Fractals (Peitgen
// and Richter, pp. 125-127): the predator-prey equations x' = x - xy,
// y' = -y + xy, stepped by a two-stage scheme of step h and weight p.
// Ported from Xfractint 20.04p16 (common/fractals.c, VLfpFractal; VLSetup
// in common/frasetup.c clamps both parameters to 0..1; the table entry in
// common/fractalp.c gives the defaults, the view and the bailout).
//
// The pixel is the starting population (x, y); the count of passes until
// it leaves the bailout's circle is the picture.

const PARAMS = #{
    h: #{ value: 0.739, min: 0.0, max: 1.0, caption: "h", hint: "The step (Fractint's first parameter), 0 to 1" },
    p: #{ value: 0.739, min: 0.0, max: 1.0, caption: "p", hint: "The scheme's weight (Fractint's second parameter), 0 to 1" },
    bailout: #{ value: 256.0, min: 4.0, caption: "Bailout", hint: "The squared radius past which a pixel has escaped (Fractint's 256)" },
};

const INFO = #{ title: "Volterra-Lotka", center: complex(3.0, 2.25), magn: 0.8888888888888888, maxiter: 150 };

fn start(pixel, p, ctx) {
    #{ z: pixel }
}

fn step(s, p) {
    // VLSetup's clamps.
    let h = if p.h < 0.0 { 0.0 } else if p.h > 1.0 { 1.0 } else { p.h };
    let k = if p.p < 0.0 { 0.0 } else if p.p > 1.0 { 1.0 } else { p.p };
    let half = h / 2.0;
    let x = s.z.re;
    let y = s.z.im;
    let xy = x * y;
    let u = x - xy;
    let w = -y + xy;
    let a = x + k * u;
    let b = y + k * w;
    let ab = a * b;
    s.z = complex(x + half * (u + (a - ab)), y + half * (w + (-b + ab)));
    s
}

fn escaped(s, p) {
    s.z.norm_sqr() > p.bailout
}

// Unity, Mark Peterson's Fractint type: "you won't find this in any
// fractal books unless they saw it here first - Mark invented it!"
// Ported from Xfractint 20.04p16 (common/fractals.c, UnityfpFractal; its
// table entry in common/fractalp.c).
//
// Each pass takes r^2 = x^2 + y^2, then y as (2 - r^2) x, and x as
// (2 - r^2) times that new y -- Fractint's order, kept. A pixel stops
// when r^2 passes 2, or when its orbit comes within a pixel of the unit
// circle: |r^2 - 1| under Fractint's `ddelmin`, the pixel's size. Here
// the pixel is a row of the view at Rows rows (Fractint's 480 by
// default), so the picture is Fractint's at that height whatever the
// window's, and deep zoom derives its equations (it reads no image
// size). The count of passes is the picture. Fractint tests a point before it maps
// it, the pixel itself first: each pass keeps the point it mapped
// (`s.prev`) and the test reads that, so the count is Fractint's --
// outside radius sqrt 2 every pixel stops on the first pass, as there --
// and deep zoom carries it as a convergent formula's previous z.

const PARAMS = #{
    rows: #{ value: 480.0, min: 50.0, max: 4000.0, caption: "Rows", hint: "The picture height whose pixel is the unit circle's tolerance (Fractint's 480 at 640 x 480): fewer rows, a wider ring of settled orbits" },
};

const INFO = #{ title: "Unity", center: complex(0.0, 0.0), magn: 1.3333333333333333, maxiter: 150 };

fn start(pixel, p, ctx) {
    #{ z: pixel, prev: pixel }
}

fn step(s, p) {
    s.prev = s.z;
    let r2 = s.z.norm_sqr();
    let y = (2.0 - r2) * s.z.re;
    let x = (2.0 - r2) * y;
    s.z = complex(x, y);
    s
}

fn escaped(s, p, ctx) {
    let r2 = s.prev.norm_sqr();
    r2 > 2.0 || (r2 - 1.0).abs() < 4.0 / (ctx.magn * p.rows)
}

// Halayka's quaternion sets: the quaternion Julia set with its step
// replaced (S. Halayka, "Some visually interesting non-standard quaternion
// fractal sets", Chaos, Solitons and Fractals 41, 2009). Use it from Escape
// mode ("Use as solid").
//
// The point (x, y, z) is the quaternion Z = (x, y, z, w), scalar part
// first, w the slice; it is stepped a few times (Iterations, 8 in the
// paper) and is in the set while |Z| stays within the threshold (4). So
// these are the shapes of a few iterations, smooth, not the limit fractal:
// raise Iterations to sharpen them.
//
// It shows quaternions in Rhai: `quat(w, x, y, z)`, `*` Hamilton's
// product, `inv`, and `sin`, `cos`, `exp`, `sinh`, `cosh` -- each the
// complex function of `t + i r` (t the scalar part, r the vector part's
// length) carried back along the vector part, Halayka's equations
// (17)-(21). `z.complex()` is that `t + i r`.
//
// The distance: each step stretches space by at most |1 + C| (or |C|)
// times the larger of |g'| along the plane and |Im g| / r across it, so
// `dr` bounds how far the orbit has been stretched, and a point whose
// orbit passes the threshold at step k is about (|Z_k| - 4) / dr_k from
// the set: a first-order reading, which holds near the surface, so no
// step outside is longer than a tenth of the cut. Inside there is no such
// bound -- an orbit that settles shrinks `dr`, and the reading
// (4 - |Z_k|) / dr_k says units where the surface is a tenth away -- so the
// complement and the surface (Halayka's figures 6 and 8) are marched
// through the set in steps of a fortieth of the cut, the reading taking
// over within one: a feature thinner than a step may be passed, as the
// paper's lattice passes what is finer than its spacing, and the surface
// is drawn a step thick on its escaped side, so a step from inside stops
// in it.
//
// Either reading is small where an orbit nearly crosses the threshold,
// near a surface or not, so it is a safe step and no measure of how near
// a surface is: `march: "inside"` has the march stop only inside the
// solid, its shadows hard and its occlusion counting what its probes land
// in. `prepare` gives the ball the march starts from and the camera
// frames, the cut's, so it grows with Size.
//
// Draw: the set; the complement, the cut less the set; or the surface
// between them, which is what the paper draws -- an isosurface of the
// lattice has no faces where the set meets the lattice's edge, so it is
// open at the box, and both of its sides show. Cut: the paper's box, or a
// ball, which opens the complement to show its tubes.
//
// Colour: what the orbit did, for the Branch Address colouring (`address`;
// `depth: 12` has the colourings read the whole orbit). Each piece of the
// surface is where |Z_k| reaches the threshold for one k -- from outside
// the orbit escapes there, from inside it comes nearest to escaping there
// -- so the step the orbit came nearest the threshold, and the angle Z_k
// makes with the real axis there, colour a piece alike from either side.
// The path's heading and length are its escape path's (Halayka 2018, the
// escape-paths variation): the direction the Bezier curve through the
// orbit leaves the point in, about the z axis, and how far the orbit runs.

const PARAMS = #{
    step: #{ value: 1, caption: "Step", choices: ["Z^n + C", "sin Z + C sin Z", "cos Z + C cos Z", "exp(Z^2) + C", "inv(sinh Z) + C inv(sinh Z)", "C inv(sinh Z) cosh Z"], hint: "Which of Halayka's steps: figures 1-2, 3-4, 5, 6, 7 and 8" },
    c: #{ value: quat(0.3, 0.5, 0.4, 0.2), caption: "C", hint: "The constant, scalar part first: Halayka's (0.3, 0.5, 0.4, 0.2)" },
    power: #{ value: 2.0, min: 2.0, max: 8.0, caption: "Power", hint: "The n of Z^n + C" },
    threshold: #{ value: 4.0, min: 1.0, max: 16.0, caption: "Threshold", hint: "A point whose |Z| passes it is outside the set (Halayka's 4)" },
    w: #{ value: 0.0, min: -2.0, max: 2.0, caption: "Slice", hint: "The quaternion's last part, which the 3D slice pins" },
    draw: #{ value: 0, caption: "Draw", choices: ["The set", "The complement", "The surface"], hint: "The set, cut; the cut less the set, the points that escape (figures 6 and 8); or the surface between them, open at the cut and seen from either side, as the paper's crude surface draws them" },
    cut: #{ value: 0, caption: "Cut", choices: ["Box", "Ball"], hint: "What the shape is cut to: the paper's box, or a ball, which opens the complement to show its insides" },
    size: #{ value: 1.5, min: 0.1, max: 8.0, caption: "Size", hint: "The box's half-width (Halayka's lattice, -1.5 to 1.5), or the ball's radius" },
    colour: #{ value: 0, caption: "Colour", choices: ["Nearest step", "Exit angle", "Step and angle", "Path heading", "Path length"], hint: "What the Branch Address colouring shows: the step the orbit came nearest the threshold, the angle it made with the real axis there, both, or its escape path's heading and length" },
};

const INFO = #{ title: "Halayka's Quaternions (Rhai)", march: "inside", depth: 12 };

// The ball the cut lies in, a hair over: a box's corner, or the ball.
fn prepare(p) {
    let r = if p.cut == 0 { 1.7320508 * p.size } else { p.size };
    #{ ball: 1.01 * r }
}

// How far a function of the plane stretches: along the plane by its
// derivative `gd`, across it by its imaginary part over the vector part's
// length.
fn stretch(gd, g, r) {
    max(gd.abs(), g.im.abs() / (r + 1e-30))
}

// The distance to a box of half-width `b` about the origin, negative
// inside.
fn box_distance(v, b) {
    let q = abs(v) - vec3(b);
    length(max(q, 0.0)) + min(max(q.x, max(q.y, q.z)), 0.0)
}

fn start(pos, p) {
    #{ z: quat(pos.x, pos.y, pos.z, p.w), at: pos, dr: 1.0, near: 1.0e30, out: false, d: 0.0,
       k: 0, peak: 0.0, nearest: 1, angle: 0.0, heading: 0.0, path: 0.0, address: 0.0 }
}

fn step(s, p) {
    let z = s.z;
    let zc = z.complex();
    let r = zc.im;
    let k = 0.0;
    if p.step == 0 {
        k = p.power * length(z) ** (p.power - 1.0);
        s.z = pow(z, p.power) + p.c;
    } else if p.step == 1 {
        k = length(1.0 + p.c) * stretch(cos(zc), sin(zc), r);
        s.z = sin(z) + p.c * sin(z);
    } else if p.step == 2 {
        k = length(1.0 + p.c) * stretch(-sin(zc), cos(zc), r);
        s.z = cos(z) + p.c * cos(z);
    } else if p.step == 3 {
        let e = exp(zc * zc);
        k = stretch(2.0 * zc * e, e, r);
        s.z = exp(z * z) + p.c;
    } else if p.step == 4 {
        let sh = sinh(zc);
        k = length(1.0 + p.c) * stretch(cosh(zc) / (sh * sh), 1.0 / sh, r);
        s.z = inv(sinh(z)) + p.c * inv(sinh(z));
    } else {
        let sh = sinh(zc);
        k = length(p.c) * stretch(1.0 / (sh * sh), cosh(zc) / sh, r);
        s.z = p.c * (inv(sinh(z)) * cosh(z));
    }
    s.dr = s.dr * k;
    let m = length(s.z);
    // A critical point (exp(Z^2)'s origin) stretches by nothing: the
    // derivative's floor keeps the estimate a number.
    let dr = max(s.dr, 1e-30);
    // Written so a point the step has no number for -- inv(sinh Z) at
    // Z = 0 -- is outside, as the paper's lattice has it.
    if !(m <= p.threshold) {
        s.out = true;
        let d = (m - p.threshold) / dr;
        s.d = if d >= 0.0 { d } else { 1.0e30 };
    } else {
        s.near = min(s.near, (p.threshold - m) / dr);
    }

    // What the colours read.
    s.k = s.k + 1;
    let moved = s.z - z;
    s.path = s.path + length(moved);
    if s.k == 1 {
        // The escape path leaves Z0 toward Z1; the point's own space is
        // the quaternion's first three parts.
        s.heading = atan2(moved.x, moved.w) / (2.0 * PI()) + 0.5;
    }
    if m > s.peak {
        let zk = s.z.complex();
        s.peak = m;
        s.nearest = s.k;
        s.angle = atan2(zk.im, zk.re) / PI();
    }
    let band = (s.nearest - 1).to_float();
    s.address = if p.colour == 0 {
        (band + 0.5) / 8.0
    } else if p.colour == 1 {
        s.angle
    } else if p.colour == 2 {
        (band + s.angle) / 8.0
    } else if p.colour == 3 {
        s.heading
    } else {
        s.path / (s.path + p.threshold)
    };
    s
}

// The orbit stops where it first leaves.
fn escaped(s, p) {
    s.out
}

fn distance(s, p) {
    // Outside, nine tenths: the stretch is the steps' largest, and the
    // reading measured at most nine tenths of the distance to the set
    // (sampled, every step), a fifth at the median; past a critical point
    // no step is longer than a tenth of the cut. Never none: the solid is
    // where the distance is none or less.
    let step = 0.025 * p.size;
    let outside = if s.out { max(min(0.9 * s.d, 0.1 * p.size), 1e-30) } else { 0.0 };
    let inside = if s.out { 0.0 } else { max(min(0.25 * s.near, step), 1e-30) };
    // Signed: the reading of the side the point is not on, negative in
    // the solid, so the normals, which the march takes where it stepped
    // in, see the surface from both sides -- and none at every face, or
    // they see the jump instead and snap toward the axes. The surface: a
    // shell a step thick on the escaped side, which a step from inside
    // the set cannot cross, measured in it to the nearer of its faces.
    let set = if p.draw == 0 {
        if s.out { outside } else { -inside }
    } else if p.draw == 1 {
        if s.out { -outside } else { inside }
    } else if s.out {
        max(outside - step, -outside)
    } else {
        inside
    };
    let cut = if p.cut == 0 { box_distance(s.at, p.size) } else { length(s.at) - p.size };
    max(set, cut)
}

// Halayka's quaternion sets: the quaternion Julia set with its step
// replaced (S. Halayka, "Some visually interesting non-standard quaternion
// fractal sets", Chaos, Solitons and Fractals 41, 2009). Use it from Escape
// mode ("Use as solid").
//
// The point (x, y, z) is the quaternion Z = (x, y, z, w), scalar part
// first, w the slice; it is stepped a few times (Iterations, 8 in the
// paper) and is in the set while |Z| stays within the threshold (4). So
// these are the shapes of a few iterations, smooth, not the limit fractal:
// raise Iterations to sharpen them.
//
// It shows quaternions in Rhai: `quat(w, x, y, z)`, `*` Hamilton's
// product, `inv`, and `sin`, `cos`, `exp`, `sinh`, `cosh` -- each the
// complex function of `t + i r` (t the scalar part, r the vector part's
// length) carried back along the vector part, Halayka's equations
// (17)-(21). `z.complex()` is that `t + i r`.
//
// The distance: each step stretches space by at most |1 + C| (or |C|)
// times the larger of |g'| along the plane and |Im g| / r across it, so
// `dr` bounds how far the orbit has been stretched, and a point whose
// orbit passes the threshold at step k is about (|Z_k| - 4) / dr_k from
// the set: a first-order reading, which holds near the surface, so no
// step outside is longer than a tenth of the cut. Inside there is no such
// bound -- an orbit that settles shrinks `dr`, and the reading
// (4 - |Z_k|) / dr_k says units where the surface is a tenth away -- so the
// complement and the surface (Halayka's figures 6 and 8) are marched
