        s.z = cos(z) + p.c * cos(z);
    } else if p.step == 3 {
        let e = exp(zc * zc);
        k = stretch(2.0 * zc * e, e, r);
        s.z = exp(z * z) + p.c;
    } else if p.step == 4 {
        let sh = sinh(zc);
        k = length(1.0 + p.c) * stretch(cosh(zc) / (sh * sh), 1.0 / sh, r);
        s.z = inv(sinh(z)) + p.c * inv(sinh(z));
    } else {
